import {createBottomTabNavigator} from '@react-navigation/botton-tabs';
import {
  StyleSheet,
  Image,
  View,
  TextInput,
  Text,
  Pressable,
} from 'react-native';
import HomeScreen from './HomeScreen';
import HeaderScreen from './HeaderScreen';
import ProfileScreen from './component/ProfileScreen';
import LoginScreen from './component/LoginScreen';
import I_CLGorGHS from './component/I_CLGorGHS';
import O_CLGorGHS from './component/O_CLGorGHS';
import Indoor_CLG from './component/Indoor_CLG';

const Tab = createBottomTabNavigator();

const Tabs = () =>{

  return(
    <Tab.navigator
    tabBarOptions = {{
      showLabel: false,
      style:{
        flex: .2,
        backgroundImage: 'linear-gradient(to right, #3437eb, #eb34d9)',
        margin: 0,
        height: 100,
        alignItems: 'center',
        justifyContent: 'center',
        flexDirection: 'row'
      }
    }}>
      <Tab.Screen name = "Login" component = {LoginScreen}/>
      <Tab.Screen name = "Home" component = {HomeScreen} options = {{
      tabBarIcon: ({focused}) =>{
        <View>
          <Image
            source = {require('../assets/homebutton.png')}
            resizeMode='contain'
            style={{
              height: 70,
              width: 70,
              marginLeft: 20,
              marginRight: 20,
            }}

          />
        </View>
      }}}/>
      <Tab.Screen name = "I_CLGorGHS" component = {I_CLGorGHS}/>
      <Tab.Screen name = "O_CLGorGHS" component = {O_CLGorGHS}/>
      <Tab.Screen name = "Indoor_CLG" component = {Indoor_CLG}/>
      
    </Tab.navigator>
  )
}
